<h1>Approval workflow configuration</h1><?php if($flash):?><div class="alert success"><?=e($flash)?></div><?php endif?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><div class="grid two"><section class="panel"><h2>Create workflow and first approval step</h2><form method="post" action="<?=e(url('/approval-workflows'))?>"><?=csrf_field()?><label>Workflow name<input name="workflow_name" required></label><label>Document type<select name="document_type"><?php foreach(['purchase_request','requisition','quotation_comparison','purchase_order','invoice','payment'] as $t):?><option value="<?=e($t)?>"><?=e(ucwords(str_replace('_',' ',$t)))?></option><?php endforeach?></select></label><label>Approver role<select name="approver_role_id" required><?php foreach($roles as $role):?><option value="<?=e($role['id'])?>"><?=e($role['name'])?></option><?php endforeach?></select></label><label>Step order<input type="number" name="step_order" min="1" value="1" required></label><label>Step name<input name="step_name" required></label><label>Branch ID (optional)<input type="number" name="branch_id"></label><label>Department ID (optional)<input type="number" name="department_id"></label><label>Minimum amount<input type="number" step="0.01" name="min_amount"></label><label>Maximum amount<input type="number" step="0.01" name="max_amount"></label><label>Currency code (optional)<input name="currency_code" maxlength="3"></label><button class="btn primary">Save workflow</button></form></section><section class="panel"><h2>Configured workflows</h2><table><tr><th>ID</th><th>Name</th><th>Document</th><th>Steps</th><th>Active</th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['id'])?></td><td><?=e($x['workflow_name'])?></td><td><?=e($x['document_type'])?></td><td><?=e($x['step_count'])?></td><td><?=e($x['is_active'])?></td></tr><?php endforeach?></table></section></div>
